/**
 * Generates supabase/seed.sql from the bundled sample content in src/data.
 * Run: npm run seed:generate   (Node 22.18+ / 24 — native TypeScript type stripping)
 */
import { writeFileSync } from "node:fs";
import { sampleExams } from "../src/data/exams.ts";
import { sampleLessons } from "../src/data/lessons.ts";
import { sampleStories } from "../src/data/stories.ts";

const q = (v: unknown) => (v === null || v === undefined ? "null" : `'${String(v).replace(/'/g, "''")}'`);
const j = (v: unknown) => `${q(JSON.stringify(v))}::jsonb`;

const lines: string[] = [
  "-- AUTO-GENERATED by scripts/generate-seed.ts — do not edit by hand.",
  "-- Run after schema.sql. Safe to re-run (upserts by id).",
  "",
  "begin;",
  "",
];

for (const l of sampleLessons) {
  lines.push(
    `insert into public.lessons (id, hsk_level, title, category, content_json) values (${q(l.id)}, ${l.hsk_level}, ${q(l.title)}, ${q(l.category)}, ${j(l.content_json)})`,
    `  on conflict (id) do update set hsk_level = excluded.hsk_level, title = excluded.title, category = excluded.category, content_json = excluded.content_json;`,
  );
}
lines.push("");
for (const s of sampleStories) {
  lines.push(
    `insert into public.parallel_stories (id, title_zh, title_id, hsk_level, content_pairs, audio_url) values (${q(s.id)}, ${q(s.title_zh)}, ${q(s.title_id)}, ${s.hsk_level}, ${j(s.content_pairs)}, ${q(s.audio_url)})`,
    `  on conflict (id) do update set title_zh = excluded.title_zh, title_id = excluded.title_id, hsk_level = excluded.hsk_level, content_pairs = excluded.content_pairs, audio_url = excluded.audio_url;`,
  );
}
lines.push("");
for (const e of sampleExams) {
  lines.push(
    `insert into public.hsk_exams (id, hsk_level, section_type, questions_json) values (${q(e.id)}, ${e.hsk_level}, ${q(e.section_type)}, ${j(e.questions_json)})`,
    `  on conflict (id) do update set hsk_level = excluded.hsk_level, section_type = excluded.section_type, questions_json = excluded.questions_json;`,
  );
}
lines.push("", "commit;", "");

writeFileSync(new URL("../supabase/seed.sql", import.meta.url), lines.join("\n"), "utf8");
console.log(`seed.sql written: ${sampleLessons.length} lessons, ${sampleStories.length} stories, ${sampleExams.length} exam sections`);
